// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val) public {
        // Set initial MinSum via SetMinSum (only works once before Initialized)
        c.SetMinSum(100);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Record MinSum after setup but before any Collect call
        uint256 minSumBefore = c.MinSum();

        // Fuzz: call Collect with arbitrary _am
        bool success;
        try c.Collect(_val) {
            success = true;
        } catch {
            success = false;
        }

        // Assert: MinSum never changes regardless of Collect outcome
        assertTrue(c.MinSum() == minSumBefore);
    }
}

